<script lang="ts">
 import {onMount} from 'svelte';
 import MapCanvas from './MapCanvas.svelte';import Chart from './Chart.svelte';import Dashboard from './Dashboard.svelte';import Icon from './Icon.svelte';import {datasetFormats,defaultSessionConfig,inputTargetFps,layerUnavailable,mapActivity,perceptionStages,profileConfig,recordEvent,type DashboardEvent} from './dashboard';
 import {policies,type Json,type WireFrame} from '../core';import {nativeRuntimeUnavailableMessage,normalizeOpenDatasetResponse,supportsDirectOpen} from '../api';
 let workspace=$state('Dashboard'),status=$state<Json>({state:'unconfigured',index:0,frames:0,policy:'distance_lod',speed:1}),telemetry=$state<Json>({}),desktop=$state<Json>({}),render=$state<Json>({}),info=$state<Json>({});
 let frame=$state.raw<WireFrame|null>(null),samples=$state<Json[]>([]),error=$state(''),notice=$state(''),busy=$state(false),catalog=$state<Json|null>(null),inspector=$state<Json|null>(null);
 let dataset=$state('generic'),sequence=$state(''),config=$state<Json>(defaultSessionConfig());
 let configText=$state(''),mode=$state('semantic'),showPoints=$state(true),showCells=$state(true),boundaries=$state(false),view=$state('orbit'),follow=$state(false),seekIndex=$state(0),preset=$state('Balanced');
 let report=$state<Json|null>(null),previousReport=$state<Json|null>(null),benchmarkState=$state('idle'),benchmarkCount=$state(100);
 let events=$state<DashboardEvent[]>([]);
 const labels:Record<string,string>={uniform5:'Uniform 5 cm',uniform40:'Uniform 40 cm',distance_lod:'Distance LOD',utility_lod:'Utility LOD'};
 const format=(value:any,decimals=1)=>typeof value==='number'&&Number.isFinite(value)?value.toLocaleString(undefined,{maximumFractionDigits:decimals}):'—';
 const mb=(value:any)=>typeof value==='number'?format(value/1048576)+' MB':'—';
 function rows(value:Json|null){const mapping=value?.mapping??value;return Object.entries(mapping?.policies??{}) as [string,Json][];}
 function quality(value:Json){return value.aggregate?.quality?.at(-1)?.elevation_vs_fine_reference?.rmse_m;}
 async function action(fn:()=>Promise<any>){busy=true;error='';notice='';try{return await fn();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function command(name:string,args:Json={}){return action(async()=>{const r=await window.veyra.command(name,args);if(r.status)status=r.status;return r;});}
let governorOverride=$state('automatic');
function syncGovernorOverride(value:unknown){if(value==='automatic'||value==='disabled'||value==='conserve')governorOverride=value;}
async function setGovernor(mode:string){const previous=governorOverride;governorOverride=mode;const response=await command('governor',{mode});if(!response)governorOverride=previous;}
function confirmSaved(ok:unknown,saved:string,cancelled:string){notice=ok?saved:cancelled;}
 function refreshText(){configText=JSON.stringify(config,null,2);}
 async function chooseDataset(){await action(async()=>{const response=await window.veyra.chooseDataset(dataset);if(!response)return;catalog=response.result??response;const first=catalog!.sequences?.find((s:Json)=>s.frames>0);sequence=first?.id??'';config={...config,dataset,dataset_root:catalog!.root,sequence};refreshText();notice='Dataset inspected. Configure the runtime to begin.';});}
 async function configure(){await action(async()=>{const next=JSON.parse(configText||JSON.stringify(config));const response=await window.veyra.configure(next);config=next;syncGovernorOverride(next.map?.governor_override);if(response.status)status=response.status;frame=null;notice='Runtime configured. Loading the first frame…';const first=await window.veyra.command('step');if(first.status)status={...status,...first.status};notice='First frame loaded. Start playback or step through the sequence.';});}
 const canDirectOpen=()=>typeof window!=='undefined'&&!!window.veyra&&supportsDirectOpen(window.veyra);
 async function openDirect(){await action(async()=>{if(!window.veyra.openDataset)throw new Error('Direct dataset open is unavailable in this shell. Choose a directory, then configure the runtime.');if(!catalog?.root)throw new Error('Choose a dataset directory first.');const response=await window.veyra.openDataset(dataset,catalog.root,sequence||undefined);const opened=normalizeOpenDatasetResponse(response);if(!opened.status)throw new Error('The backend did not return a session status.');catalog=opened.catalog??catalog;sequence=opened.sequence||sequence;config={...config,dataset,dataset_root:catalog!.root,sequence};syncGovernorOverride(config.map?.governor_override);refreshText();status=opened.status;frame=null;notice='Dataset opened with safe defaults. Loading the first frame…';const first=await window.veyra.command('step');if(first.status)status={...status,...first.status};notice='First frame loaded. Start playback or step through the sequence.';});}
 function applyPreset(){config=profileConfig(config,preset);governorOverride='automatic';refreshText();}
 onMount(()=>{
  refreshText();if(!window.veyra){error=nativeRuntimeUnavailableMessage;return;}
  void action(async()=>{info=await window.veyra.info();if(info.status)status=info.status;});
  const off=window.veyra.onEvent(event=>{
   events=recordEvent(events,event);
   if(event.type==='status'){status={...status,...event};if(event.error)error=event.error.process+': '+event.error.message;}
   if(event.type==='telemetry'){telemetry=event;const latency=event.latency_ms??{};samples=[...samples,{timestamp:event.timestamp,fps:event.fps,p95:latency.end_to_end?.p95,rss:(event.processes??[]).reduce((sum:number,p:Json)=>sum+(p.rss_bytes??0),0)/1048576,mapping:latency.mapping,perception:latency.perception}].slice(-300);status={...status,index:event.index,frames:event.frames,state:event.state};}
   if(event.type==='desktop_telemetry')desktop=event;
   if(event.type==='benchmark'){benchmarkState=event.state;if(event.report)report=event.report;if(event.error)error=String(event.error.message??event.error);}
  });
  const offVisual=window.veyra.onVisualization(value=>{if(frame&&value.metadata.generation<frame.metadata.generation)return;frame=value;});
  return()=>{off();offVisual();};
 });
</script>

<div class="application">
 <aside class="rail">
  <div class="brand"><span class="brand-mark"><i></i></span><span>VEYRA<small>Map smarter.<br/>Move safer.</small></span></div>
  <nav aria-label="Workspaces">{#each [['Dashboard','Dashboard','home'],['Map','Live Mapping','map'],['Datasets','Datasets','database'],['Benchmarks','Benchmarks','chart'],['Configuration','Settings','settings']] as [key,name,icon]}<button class:active={workspace===key} onclick={()=>workspace=key}><Icon name={icon}/>{name}</button>{/each}</nav>
  <div class="rail-bottom"><div class="system-health"><h3><i class:online={['ready','running','paused','ended'].includes(status.state)}></i>{['ready','running','paused','ended'].includes(status.state)?'System Online':'Runtime Standby'}</h3>{#each [['LiDAR',!!frame],['Localization',frame?.metadata.pose_available===true],['Mapping',telemetry.map?.active_cells!=null],['Perception',!!frame?.metadata.layers?.semantic&&frame.metadata.layers.semantic!=='unavailable']] as [name,available]}<div><span>{name}</span><b class:available>{available?'✓':'—'}</b></div>{/each}</div><strong>VEYRA · SIH 2026</strong><p>Adaptive Mapping for<br/>Safer Autonomy</p><span class="muted">v{info.version??'0.1.0'} · {info.platform??'desktop'}</span></div>
 </aside>
 <main>
  <header><div class="header-title"><div><h1>{workspace==='Dashboard'?'Adaptive 2.5D LiDAR Dashboard':workspace==='Map'?'Live Mapping':workspace==='Performance'?'Runtime Performance':workspace==='Benchmarks'?'Policy Benchmarks':workspace==='Datasets'?'Dataset Management':'Session Settings'}</h1><span class="status-pill" class:running={status.state==='running'} class:failed={status.state==='error'}><i></i>{status.state==='running'?'Live':status.state}</span>{#if telemetry.stale===true}<span class="stale-badge" title="Flagged by the desktop shell: this telemetry arrived more than 30 s after its timestamp. Values may be outdated.">STALE</span>{/if}</div><p>Real-time mapping · Adaptive resolution · Semantic understanding</p></div><div class="header-right"><div class="scenario-control"><label for="header-scenario">Scenario</label><div><Icon name="car" size={17}/><select id="header-scenario" value={status.sequence??''} onchange={event=>command('sequence',{sequence:event.currentTarget.value})} disabled={!catalog?.sequences?.length}><option value="">{status.sequence??'No dataset selected'}</option>{#each catalog?.sequences??[] as item}<option value={item.id}>{item.id} · {item.frames} frames</option>{/each}</select></div></div><button class="export-button" onclick={()=>action(async()=>{const saved=await window.veyra.diagnostics();confirmSaved(saved,'Diagnostics exported.','Diagnostics export cancelled — no file written.');})}><Icon name="export" size={18}/>Export</button><div class="local-profile"><span>V</span><div><strong>Local Session</strong><small>Veyra Runtime</small></div></div></div></header>
  {#if error}<div class="alert" role="alert"><span>{error}</span><button onclick={()=>action(async()=>{const r=await window.veyra.restart();status=r.status??status;error='';})}>Restart runtime</button><button aria-label="Dismiss error" onclick={()=>error=''}>×</button></div>{/if}
  {#if notice}<div class="notice" role="status">{notice}</div>{/if}
  {#if workspace==='Dashboard'}
   <Dashboard {status} {telemetry} {frame} {report} {events} openDataset={()=>workspace='Datasets'} openPerformance={()=>workspace='Performance'} runCommand={(name,args)=>{void command(name,args);}}/>
  {:else if workspace==='Map'}
   <div class="map-workspace">
    <aside class="layer-panel"><div class="panel-heading">LAYERS <span>DISPLAY</span></div>
     <label class="toggle"><input type="checkbox" bind:checked={showPoints}/>Raw LiDAR</label><label class="toggle"><input type="checkbox" bind:checked={showCells}/>Adaptive map</label><div class="separator"></div>
     {#each [['semantic','Semantic'],['elevation','Elevation'],['ground','Ground'],['terrain','Traversability'],['motion','Motion'],['lod','LOD resolution'],['utility','Utility']] as [value,label]}
      <button class="layer" class:selected={mode===value} onclick={()=>mode=value}><span class="layer-dot" style:background={value==='lod'?'#45d3c9':undefined}></span>{label}{#if layerUnavailable(frame,value)}<small>n/a</small>{/if}</button>
     {/each}
     <div class="separator"></div><label class="toggle"><input type="checkbox" bind:checked={boundaries}/>Cell boundaries</label><label class="toggle"><input type="checkbox" bind:checked={follow}/>Follow robot</label>
     <div class="panel-heading space-top">RESOLUTION</div>{#each ['5 cm','10 cm','20 cm','40 cm'] as level,i}<div class="legend-row"><i style:background={['#33d9f2','#4dd980','#ffb340','#d966d9'][i]}></i><span>L{i} · {level}</span><b>{format(telemetry.map?.cells_by_level?.[i],0)}</b></div>{/each}
     {#if inspector}<div class="inspector"><div class="panel-heading">CELL INSPECTOR</div>{#each Object.entries(inspector) as [key,value]}<div><span>{key.replaceAll('_',' ')}</span><b>{format(value,3)}</b></div>{/each}<button onclick={()=>inspector=null}>Close</button></div>{:else}<p class="hint">Double-click a cell to inspect its measured fields.</p>{/if}
    </aside>
    <section class="map-stage" aria-label="LiDAR and adaptive map">
     <MapCanvas {frame} {mode} {showPoints} {showCells} {boundaries} {view} {follow} onStats={value=>render=value} onInspect={value=>inspector=value}/>
     <div class="map-toolbar"><div class="segmented">{#each ['orbit','top','driver'] as camera}<button class:active={view===camera} onclick={()=>view=camera}>{camera}</button>{/each}</div><button onclick={()=>action(async()=>{const saved=await window.veyra.screenshot();confirmSaved(saved,'Screenshot saved.','Screenshot cancelled — no file written.');})}>↓ Screenshot</button></div>
     {#if !frame}<div class="map-empty"><div class="empty-orbit">◈</div><h2>Your environment, mapped.</h2><p>Choose a dataset and configure a session to see<br/>real LiDAR observations and adaptive map cells.</p><button class="primary" onclick={()=>workspace='Configuration'}>Open configuration →</button></div>{/if}
     <div class="map-coordinate"><span>WORLD · ODOM</span><span>{format(frame?.metadata.points?.count,0)} points · {format(frame?.metadata.cells?.count,0)} cells displayed</span></div>
     {#if frame&&layerUnavailable(frame,mode)}<div class="layer-warning">{mode[0].toUpperCase()+mode.slice(1)} values are unavailable in the current map snapshot.</div>{/if}
    </section>
   </div>
   <div class="playback"><div class="playback-buttons"><button title="Reset map" disabled={busy||status.state==='unconfigured'} onclick={()=>command('reset')}>↺</button><button class="play-button" disabled={busy||status.state==='unconfigured'} onclick={()=>command(status.state==='running'?'pause':'start')}>{status.state==='running'?'Ⅱ':'▶'}</button><button title="Step frame" disabled={busy||status.state==='unconfigured'} onclick={()=>command('step')}>▸|</button></div><div class="timeline"><div><span>FRAME {format(status.index,0)}</span><span>{format(status.frames,0)} frames</span></div><input aria-label="Seek frame" type="range" min="0" max={Math.max(0,(status.frames??1)-1)} value={status.index??0} oninput={event=>seekIndex=Number(event.currentTarget.value)} onchange={()=>command('seek',{index:seekIndex})} disabled={busy||!status.frames}/></div><select aria-label="Playback speed" value={status.speed??1} onchange={event=>command('speed',{speed:Number(event.currentTarget.value)})}>{#each [.25,.5,1,2,4,8] as speed}<option value={speed}>{speed}×</option>{/each}</select><select aria-label="Mapping policy" value={status.policy??'distance_lod'} onchange={event=>command('policy',{policy:event.currentTarget.value})}>{#each policies as policy}<option value={policy}>{labels[policy]}</option>{/each}</select></div>
   <div class="metric-strip"><div><span>RUNTIME FPS</span><b>{format(telemetry.fps)}</b></div><div title="Target playback rate = session playback.fps × speed (Python tick scheduler). Shows — when the session has no playback rate."><span>INPUT TARGET</span><b>{format(inputTargetFps(config,status))} <small>fps</small></b></div><div><span>FRAME p95</span><b>{format(telemetry.latency_ms?.end_to_end?.p95)} <small>ms</small></b></div><div><span>MAPPER RSS</span><b>{mb(telemetry.processes?.find((p:Json)=>p.name==='mapper')?.rss_bytes)}</b></div><div><span>ACTIVE CELLS</span><b>{format(telemetry.map?.active_cells,0)}</b></div><div><span>RENDER FPS</span><b>{format(render.fps)}</b></div><div><span>DROPPED FRAMES</span><b>{format(telemetry.dropped_frames,0)}</b></div></div>
  {:else if workspace==='Performance'}
   <div class="workspace-scroll"><div class="page-intro"><div><h2>Every stage, accounted for.</h2><p>Live process measurements. Rolling history retains the latest 300 samples.</p></div><span class="chip">{status.config_digest?.slice(0,12)??'NO SESSION'}</span></div>
    <div class="stats-grid">{#each [['Runtime FPS',telemetry.fps,'fps'],['Frame p50',telemetry.latency_ms?.end_to_end?.p50,'ms'],['Frame p95',telemetry.latency_ms?.end_to_end?.p95,'ms'],['Frame p99',telemetry.latency_ms?.end_to_end?.p99,'ms']] as [label,value,unit]}<div class="stat-card"><span>{label}</span><strong>{format(value)} <small>{unit}</small></strong></div>{/each}</div>
    <div class="chart-grid"><section class="card"><h3>Throughput <span>FPS</span></h3><Chart {samples} metric="fps" label="Runtime FPS"/></section><section class="card"><h3>End-to-end latency <span>p95 · ms</span></h3><Chart {samples} metric="p95" label="Frame p95" color="#c29cff"/></section><section class="card"><h3>Python backend memory <span>RSS · MB</span></h3><Chart {samples} metric="rss" label="Python backend RSS" color="#ffba6b"/></section><section class="card"><h3>Mapper latency <span>ms</span></h3><Chart {samples} metric="mapping" label="Mapping" color="#78b9ff"/></section></div>
    <div class="two-columns"><section class="card"><h3>Processes <span>CPU / memory</span></h3><table><thead><tr><th>Process</th><th>PID</th><th>CPU</th><th>RSS</th></tr></thead><tbody>{#each [...(telemetry.processes??[]),...(desktop.processes??[])] as process}<tr><td>{process.name}</td><td>{process.pid??'—'}</td><td>{format(process.cpu_percent)}%</td><td>{mb(process.rss_bytes)}</td></tr>{/each}</tbody></table><p class="hint">CPU may exceed 100% across cores. Unavailable measurements display —. Python rows are measured per frame by the Python reporter; desktop shell rows arrive via desktop_telemetry (Electron, 1 Hz) and are absent in Tauri builds, which emit no desktop_telemetry.</p></section><section class="card"><h3>Frame stages <span>ms</span></h3>{#each [['Perception',telemetry.latency_ms?.perception],['Bridge / IPC',telemetry.latency_ms?.ipc],['C++ mapping',telemetry.latency_ms?.mapping],['Visualization preparation',telemetry.latency_ms?.visualization],['Renderer',render.latency_ms],...Object.entries(telemetry.perception_stages_ms??{})] as [label,value]}<div class="data-row"><span>{label}</span><b>{format(value,2)}</b></div>{/each}</section></div>
    <section class="card perception-status"><h3>Perception evidence <span>{frame?.metadata.dataset??'NO FRAME'}</span></h3><div class="stage-grid">{#each perceptionStages(frame) as stage}<div class="stage-item"><span>{stage.label}</span><strong class:stage-available={stage.status==='available'||stage.status==='model'||stage.status==='ground_truth'} class:stage-unavailable={stage.status==='unavailable'||stage.status==='invalid'}>{stage.status}</strong><small>{format(stage.latency,2)} ms</small></div>{/each}</div><p class="hint">Status is reported by the active pipeline; unavailable and skipped evidence is never rendered as measured data.</p></section>
    <div class="two-columns"><section class="card"><h3>Map allocation</h3>{#each mapActivity(telemetry) as [label,value]}<div class="data-row"><span>{label}</span><b>{label.includes('bytes')?mb(value):format(value,label.includes('second')?2:0)}</b></div>{/each}</section><section class="card"><h3>Resource governor <span>{telemetry.governor?.state??'unavailable'}</span></h3><label for="governor-override">Manual override</label><select id="governor-override" aria-label="Governor override" value={governorOverride} title={busy?'Governor control unavailable while a command is running.':!status.frames?'Configure a dataset session before overriding the governor.':'Manual governor override. Backend state is shown above.'} disabled={busy||!status.frames} onchange={event=>{void setGovernor(event.currentTarget.value);}}><option value="automatic">Automatic</option><option value="disabled">Disabled (debug)</option><option value="conserve">Conserve resources</option></select><div class="data-row"><span>Queue depth</span><b>{format(telemetry.queue_depth,0)}</b></div><div class="data-row"><span>Dropped frames</span><b>{format(telemetry.dropped_frames,0)}</b></div><div class="data-row"><span>Visualization superseded</span><b>{format(telemetry.visualization_dropped,0)}</b></div><div class="data-row"><span>Desktop updates superseded</span><b>{format(desktop.ui_visualization_dropped,0)}</b></div>{#if desktop.ui_visualization_dropped==null}<p class="hint">Desktop shell counter unavailable — this shell emits no desktop_telemetry (Tauri).</p>{/if}<pre>{JSON.stringify(telemetry.governor?.budget??{budget:'unavailable'},null,2)}</pre></section></div>
   </div>
  {:else if workspace==='Benchmarks'}
   <div class="workspace-scroll"><div class="page-intro"><div><h2>Quality has a resource cost.</h2><p>Compare all four policies using the same report schema as CI.</p></div><span class="chip">{benchmarkState.toUpperCase()}</span></div><section class="card benchmark-controls"><div><label for="benchmark-count">Frames</label><input id="benchmark-count" type="number" min="1" max="100000" bind:value={benchmarkCount}/></div><button class="primary" disabled={busy||!status.dataset} onclick={()=>action(async()=>{benchmarkState='running';const response=await window.veyra.command('benchmark',{dataset:status.dataset,sequence:status.sequence,count:benchmarkCount});if(response.result?.report)report=response.result.report;})}>Run four-policy benchmark</button><button onclick={()=>action(async()=>{const loaded=await window.veyra.openReport();if(loaded){previousReport=report;report=loaded;}})}>Open report</button><button disabled={!report} onclick={()=>action(async()=>{const saved=await window.veyra.exportReport(report!);confirmSaved(saved,'Benchmark report exported.','Benchmark export cancelled — no file written.');})}>Export JSON</button><button onclick={()=>action(async()=>{previousReport=await window.veyra.openReport();})}>Compare previous run</button></section>
    {#if report}<section class="card"><h3>Policy comparison <span>schema {report.schema_version??report.mapping?.schema_version??'—'}</span></h3><table><thead><tr><th>Policy</th><th>FPS p50</th><th>Map p95</th><th>Peak RSS</th><th>Active leaves</th><th>Elevation RMSE</th></tr></thead><tbody>{#each rows(report) as [policy,result]}<tr><td>{labels[policy]??policy}</td><td>{format(result.aggregate?.fps?.p50)}</td><td>{format(result.aggregate?.stage_latency_ns?.map_update?.p95/1e6)} ms</td><td>{mb(result.aggregate?.peak_rss_bytes)}</td><td>{format(Object.values(result.aggregate?.final_leaves_per_level??{}).reduce((a:any,b:any)=>a+b,0),0)}</td><td>{format(quality(result),4)} m</td></tr>{/each}</tbody></table></section>{#if previousReport}<section class="card"><h3>Previous run comparison</h3><table><thead><tr><th>Policy</th><th>Current p95</th><th>Previous p95</th><th>Current RMSE</th><th>Previous RMSE</th></tr></thead><tbody>{#each rows(report) as [policy,result]}{@const previous=rows(previousReport).find(([key])=>key===policy)?.[1]}<tr><td>{labels[policy]??policy}</td><td>{format(result.aggregate?.stage_latency_ns?.map_update?.p95/1e6)} ms</td><td>{format(previous?.aggregate?.stage_latency_ns?.map_update?.p95/1e6)} ms</td><td>{format(quality(result),4)}</td><td>{previous?format(quality(previous),4):'—'}</td></tr>{/each}</tbody></table></section>{/if}<details class="card"><summary>Full benchmark artifact</summary><pre>{JSON.stringify(report,null,2)}</pre></details>{:else}<div class="blank-card"><span>▤</span><h2>No benchmark loaded</h2><p>Configure a dataset session, then run a measured comparison.<br/>Existing JSON artifacts can be opened at any time.</p></div>{/if}
   </div>
  {:else}
   <div class="workspace-scroll"><div class="page-intro"><div><h2>A reproducible session starts here.</h2><p>Dataset, perception and map settings are validated before startup.</p></div><button onclick={()=>action(async()=>{const loaded=await window.veyra.openConfig();if(loaded){config=loaded;dataset=loaded.dataset??dataset;sequence=loaded.sequence??'';syncGovernorOverride(loaded.map?.governor_override);refreshText();notice='Configuration loaded. Choose its dataset directory before applying.';}})}>Import configuration</button></div>
    <div class="two-columns"><section class="card"><h3>Dataset <span>LOCAL FILES</span></h3><label for="dataset-format">Dataset format</label><select id="dataset-format" bind:value={dataset}>{#each datasetFormats as [value,label]}<option value={value}>{label}</option>{/each}</select><button class="wide" disabled={busy} onclick={chooseDataset}>Choose dataset directory…</button>{#if catalog}<div class="dataset-result"><span class="chip">{catalog.status}</span><p>{catalog.root}</p>{#each catalog.diagnostics??[] as diagnostic}<p class="hint">{diagnostic}</p>{/each}</div><label for="sequence">Sequence</label><select id="sequence" bind:value={sequence} onchange={()=>{config={...config,sequence};refreshText();}}>{#each catalog.sequences??[] as seq}<option value={seq.id}>{seq.id} · {seq.frames} frames · {seq.labels} labels</option>{/each}</select><table><thead><tr><th>Sequence</th><th>Frames</th><th>Pose</th><th>Time</th></tr></thead><tbody>{#each catalog.sequences??[] as seq}<tr><td>{seq.id}</td><td>{seq.frames}</td><td>{seq.poses===null?'unknown':seq.poses?'yes':'no'}</td><td>{seq.timestamps===null?'unknown':seq.timestamps?'yes':'no'}</td></tr>{/each}</tbody></table>{#if canDirectOpen()}<button class="wide primary" disabled={busy||!catalog?.root} onclick={openDirect}>Open dataset with safe defaults</button>{/if}{:else}<p class="hint">Data stays in its original directory. A generic dataset uses a manifest.json file.</p>{/if}</section>
     <section class="card"><h3>Display profile <span>BOUNDED UPDATES</span></h3><div class="preset-grid">{#each ['Performance','Balanced','Quality'] as name}<button class:active={preset===name} onclick={()=>{preset=name;applyPreset();}}>{name}</button>{/each}</div><div class="data-row"><span>Point display budget</span><b>{format(config.visualization?.point_budget,0)}</b></div><div class="data-row"><span>Cell display budget</span><b>{format(config.visualization?.cell_budget,0)}</b></div><div class="data-row"><span>Visualization updates</span><b>{config.visualization?.update_hz} Hz</b></div><p class="hint">Display budgets are independent of map ingestion. Mapping processes all observations in each accepted frame.</p><label for="default-policy">Map policy</label><select id="default-policy" value={config.map?.policy} onchange={event=>{config={...config,map:{...config.map,policy:event.currentTarget.value}};refreshText();}}>{#each policies as policy}<option value={policy}>{labels[policy]}</option>{/each}</select></section></div>
    <section class="card"><h3>Session configuration <span>JSON</span></h3><textarea aria-label="Session configuration JSON" bind:value={configText} spellcheck="false" rows="17"></textarea><div class="form-actions"><button disabled={busy} onclick={()=>action(async()=>{await window.veyra.validateConfig(JSON.parse(configText));notice='Configuration is valid.';})}>Validate</button><button disabled={busy} onclick={()=>action(async()=>{const saved=await window.veyra.saveConfig(JSON.parse(configText));confirmSaved(saved,'Configuration preset saved.','Preset save cancelled — no file written.');})}>Save preset</button><button class="primary" disabled={busy} onclick={configure}>{busy?'Working…':'Configure runtime'}</button></div></section>
   </div>
  {/if}
 </main>
</div>
